/**
 * TodoMVC - Vanilla JS
 * @planks("there are no todos")
 * @planks("{string} is not visible")
 * @planks("I see {int} todo in the list")
 * @planks("I see {int} todos in the list")
 * @planks("I press Enter")
 * @planks("the new todo has title {string}")
 * @planks("the new todo is not completed")
 * @planks("the input is cleared")
 * @planks("all todos are completed")
 * @planks("{string} is checked")
 * @planks("{string} is not checked")
 * @planks("the first todo has class {string}")
 * @planks("the todo count shows {string}")
 * @planks("the first todo has title {string}")
 * @planks("the first todo does not have class {string}")
 * @planks("I double-click the first todo label")
 * @planks("I press Enter in the edit field")
 * @planks("the editing input loses focus")
 * @planks("I press Escape in the edit field")
 * @planks("I navigate to {string}")
 * @planks("the {string} filter link has class {string}")
 */
(function () {
  'use strict';

  const STORAGE_KEY = 'todos-vanillajs';

  // ── Model ─────────────────────────────────────────────────────

  function getTodos() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (_) {
      return [];
    }
  }

  function setTodos(todos) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  // ── Controller ────────────────────────────────────────────────

  var ENTER_KEY = 13;

  var todoApp = {
    todos: [],
    filter: 'all',

    init: function () {
      this.todos = getTodos();
      this.filter = this.getCurrentFilter();
      this.render();
      this.bindEvents();
    },

    getCurrentFilter: function () {
      var hash = window.location.hash || '#';
      if (hash === '#/active') return 'active';
      if (hash === '#/completed') return 'completed';
      return 'all';
    },

    getFilteredTodos: function () {
      var self = this;
      return this.todos.filter(function (t) {
        if (self.filter === 'active') return !t.completed;
        if (self.filter === 'completed') return t.completed;
        return true;
      });
    },

    render: function () {
      var main = document.querySelector('.main');
      var footer = document.querySelector('.footer');
      var todoList = document.querySelector('.todo-list');
      var todoCount = document.querySelector('.todo-count');
      var clearBtn = document.querySelector('.clear-completed');
      var filters = document.querySelectorAll('.filters a');

      // Update filter link selected class
      filters.forEach(function (link) {
        var href = link.getAttribute('href');
        if ((href === '#/' && todoApp.filter === 'all') ||
            (href === '#/active' && todoApp.filter === 'active') ||
            (href === '#/completed' && todoApp.filter === 'completed')) {
          link.className = 'selected';
        } else {
          link.className = '';
        }
      });

      // Render filtered todo items from model
      todoList.innerHTML = '';
      var self = this;
      var filteredTodos = this.getFilteredTodos();
      filteredTodos.forEach(function (todo) {
        var li = document.createElement('li');
        if (todo.completed) li.className = 'completed';
        li.innerHTML = '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
          '<label>' + todo.title + '</label>' +
          '<button class="destroy"></button>' +
          '</div>' +
          '<input class="edit" value="' + todo.title + '">';
        todoList.appendChild(li);
        // Attach blur handler to the edit input
        var editInput = li.querySelector('.edit');
        if (editInput) self.attachEditBlur(editInput);
      });

      // Update toggle-all state
      var ta = document.getElementById('toggle-all');
      if (ta) {
        ta.checked = this.todos.length > 0 && this.todos.every(function (t) { return t.completed; });
      }

      // Update counter (always based on all todos)
      if (todoCount) {
        var activeCount = this.todos.filter(function (t) { return !t.completed; }).length;
        todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + (activeCount === 1 ? 'item' : 'items') + ' left';
      }

      // Show/hide clear-completed
      if (clearBtn) {
        var hasCompleted = this.todos.some(function (t) { return t.completed; });
        clearBtn.style.display = hasCompleted ? 'block' : 'none';
      }

      // Show/hide main and footer based on whether there are todos (all, not filtered)
      if (this.todos.length === 0) {
        main.style.display = 'none';
        footer.style.display = 'none';
      } else {
        main.style.display = 'block';
        footer.style.display = 'block';
      }
    },

    bindEvents: function () {
      var self = this;

      // Route changes
      window.addEventListener('hashchange', function () {
        self.filter = self.getCurrentFilter();
        self.render();
      });

      var newTodo = document.querySelector('.new-todo');

      if (newTodo) {
        newTodo.addEventListener('keypress', function (e) {
          if (e.keyCode === ENTER_KEY || e.key === 'Enter') {
            var val = newTodo.value.trim();
            if (val !== '') {
              self.addTodo(val);
            }
            newTodo.value = '';
          }
        });
      }

      // Toggle all
      var toggleAll = document.getElementById('toggle-all');
      if (toggleAll) {
        toggleAll.addEventListener('change', function () {
          self.toggleAll(this.checked);
        });
      }

      // Clear completed
      var clearBtn = document.querySelector('.clear-completed');
      if (clearBtn) {
        clearBtn.addEventListener('click', function () {
          self.clearCompleted();
        });
      }

      // Delegate events on todo-list (toggle, destroy, dblclick)
      var todoList = document.querySelector('.todo-list');
      if (todoList) {
        todoList.addEventListener('change', function (e) {
          var toggle = e.target.closest('.toggle');
          if (!toggle) return;
          var li = toggle.closest('li');
          var index = Array.prototype.indexOf.call(todoList.children, li);
          if (index !== -1) {
            self.toggleTodo(index);
          }
        });

        todoList.addEventListener('click', function (e) {
          var destroy = e.target.closest('.destroy');
          if (!destroy) return;
          var li = destroy.closest('li');
          var index = Array.prototype.indexOf.call(todoList.children, li);
          if (index !== -1) {
            self.removeTodo(index);
          }
        });

        todoList.addEventListener('dblclick', function (e) {
          var label = e.target.closest('label');
          if (!label) return;
          var li = label.closest('li');
          var items = Array.prototype.indexOf.call(todoList.children, li);
          li.classList.add('editing');
          var editInput = li.querySelector('.edit');
          if (editInput) {
            editInput.value = self.todos[items].title;
            editInput.focus();
          }
        });

        // Edit keydown (Enter saves, Escape cancels)
        todoList.addEventListener('keydown', function (e) {
          if (e.key !== 'Enter' && e.key !== 'Escape') return;
          var editInput = e.target.closest('.edit');
          if (!editInput) return;
          var li = editInput.closest('li');
          var index = Array.prototype.indexOf.call(todoList.children, li);
          if (e.key === 'Enter') {
            self.commitEdit(index, editInput.value);
          } else if (e.key === 'Escape') {
            self.cancelEdit(index);
          }
        });

        // Edit input blur saves - attached directly in render
      }
    },

    attachEditBlur: function (editInput) {
      var self = this;
      editInput.addEventListener('blur', function () {
        var li = editInput.closest('li');
        if (!li) return;
        var index = Array.prototype.indexOf.call(
          document.querySelector('.todo-list').children, li
        );
        self.commitEdit(index, editInput.value);
      });
    },

    addTodo: function (title) {
      this.todos.push({
        id: Date.now() + Math.random(),
        title: title,
        completed: false
      });
      setTodos(this.todos);
      this.render();
    },

    toggleAll: function (checked) {
      this.todos.forEach(function (todo) {
        todo.completed = checked;
      });
      setTodos(this.todos);
      this.render();
    },

    toggleTodo: function (index) {
      if (index >= 0 && index < this.todos.length) {
        this.todos[index].completed = !this.todos[index].completed;
        setTodos(this.todos);
        this.render();
      }
    },

    removeTodo: function (index) {
      if (index >= 0 && index < this.todos.length) {
        this.todos.splice(index, 1);
        setTodos(this.todos);
        this.render();
      }
    },

    clearCompleted: function () {
      this.todos = this.todos.filter(function (t) { return !t.completed; });
      setTodos(this.todos);
      this.render();
    },

    commitEdit: function (index, value) {
      var title = value.trim();
      if (title === '') {
        // Empty input destroys the todo
        this.removeTodo(index);
      } else if (index >= 0 && index < this.todos.length) {
        this.todos[index].title = title;
        setTodos(this.todos);
        this.render();
      }
    },

    cancelEdit: function (index) {
      this.render();
    }
  };

  // ── Boot ──────────────────────────────────────────────────────

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () { todoApp.init(); });
  } else {
    todoApp.init();
  }

  // Expose for test harness to trigger reinit
  window.__todoApp = todoApp;
})();

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

